CREATE TABLE "app_notifications" ("id" UUID PRIMARY KEY, "user_id" UUID NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "pet_id" UUID NOT NULL REFERENCES "pets"("id") ON DELETE CASCADE, "event_key" TEXT NOT NULL UNIQUE, "kind" TEXT NOT NULL, "subject" TEXT NOT NULL, "due_on" DATE NOT NULL, "offset_days" INTEGER NOT NULL, "read_at" TIMESTAMPTZ(6), "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "app_notifications_user_id_created_at_idx" ON "app_notifications"("user_id", "created_at");
CREATE TABLE "push_subscriptions" ("id" UUID PRIMARY KEY, "user_id" UUID NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "endpoint" TEXT NOT NULL UNIQUE, "p256dh" TEXT NOT NULL, "auth" TEXT NOT NULL, "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "push_subscriptions_user_id_idx" ON "push_subscriptions"("user_id");
CREATE TABLE "push_deliveries" ("id" UUID PRIMARY KEY, "notification_id" UUID NOT NULL REFERENCES "app_notifications"("id") ON DELETE CASCADE, "subscription_id" UUID NOT NULL REFERENCES "push_subscriptions"("id") ON DELETE CASCADE, "status" TEXT NOT NULL DEFAULT 'pending', "attempts" INTEGER NOT NULL DEFAULT 0, "next_attempt_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, "lease_until" TIMESTAMPTZ(6), UNIQUE("notification_id", "subscription_id"));
CREATE INDEX "push_deliveries_status_next_attempt_at_idx" ON "push_deliveries"("status", "next_attempt_at");
